var nation_facts = relationOfFacts(lpFacts['nation/3'] || []);
var supplier_facts = relationOfFacts(lpFacts['supplier/2'] || []);
var orders_facts = relationOfFacts(lpFacts['orders/5'] || []);
var lineitem_facts = relationOfFacts(lpFacts['lineitem/13'] || []);

var orders = orders_facts;

var orders_by_3 = index(orders, [2]);
var instances_finished_order = [].concat(
  // finished_order(O) :- orders(O,_,f,_,_).
  (function() {
    return _.flatten(map(function(e1) {
      var O = e1.t[0];
      return [['finished_order', [O], e1.v]];
    }, (orders_by_3[keyOf(['f'])] || [])));
  })()
);
var finished_order = relation({}, instances_finished_order);

var lineitem = lineitem_facts;

var instances_late_delivery = [].concat(
  // late_delivery(S,O) :- lineitem(O,_,_,S,_,_,_,_,_,Commit,Receipt,_,_), Receipt > Commit.
  (function() {
    return _.flatten(map(function(e1) {
      var O = e1.t[0];
      var S = e1.t[3];
      var Commit = e1.t[9];
      var Receipt = e1.t[10];
      if (Receipt > Commit) {
        return [['late_delivery', [S, O], e1.v]];
      } else {
        return [];
      }
    }, _.values(lineitem)));
  })()
);
