      var S = e1.t[0];
      return _.flatten(map(function(e2) {
        var O = e2.t[1];
        return _.flatten(map(function(e3) {
          return [['waiting_supplier', [S], and([e1.v, e2.v, e3.v])]];
        }, probe(finished_order, [O])));
      }, (late_delivery_by_1[keyOf([S])] || [])));
    }, _.values(saudi_supplier)));
  })()
);
