var instances_q21 = [].concat(
  // q21 :- waiting_supplier(_).
  (function() {
    return _.flatten(map(function(e1) {
      return [['q21', [], e1.v]];
    }, _.values(waiting_supplier)));
  })()
);
var q21 = relation({}, instances_q21);

// component 0 bool
var model = function() {
  return [holds(q21, [])()];
};
